from collections import Counter

from molecule import AROMATIC, ORGANIC, needs_pi, organic_hydrogens


def dense_ranks(values):
    ranks = {value: index for index, value in enumerate(sorted(set(values)), 1)}
    return [ranks[value] for value in values]


def refine(molecule, ranks):
    while True:
        values = [(ranks[atom], tuple(sorted((ranks[neighbor], bond.kind)
                                            for neighbor, bond in neighbors.items())))
                  for atom, neighbors in enumerate(molecule.neighbors)]
        new_ranks = dense_ranks(values)
        if len(set(new_ranks)) == len(set(ranks)):
            return new_ranks
        ranks = new_ranks


def canonical_ranks(molecule):
    invariants = [(molecule.degree(number), atom.element.number, atom.mass,
                   atom.charge, atom.hydrogens, int(atom.aromatic))
                  for number, atom in enumerate(molecule.atoms)]
    ranks = refine(molecule, dense_ranks(invariants))
    classes = len(set(ranks))
    while len(set(ranks)) != len(ranks):
        counts = Counter(ranks)
        tied_rank = min(rank for rank, count in counts.items() if count > 1)
        first = ranks.index(tied_rank)
        values = [2 * rank - int(number == first) for number, rank in enumerate(ranks)]
        ranks = refine(molecule, dense_ranks(values))
    return ranks, classes


def atom_notation(molecule, number):
    atom = molecule.atoms[number]
    symbol = atom.element.symbol
    ordinary = symbol in ORGANIC and (not atom.aromatic or symbol in AROMATIC)
    ordinary = ordinary and atom.mass == 0 and atom.charge == 0
    if atom.aromatic:
        ordinary = ordinary and needs_pi(molecule, number) == needs_pi(molecule, number, 0)
        symbol = symbol.lower()
    hydrogens = organic_hydrogens(atom, molecule.bond_total(number))
    if ordinary and hydrogens is not None and hydrogens == atom.hydrogens:
        return symbol
    text = "[" + (str(atom.mass) if atom.mass else "") + symbol
    if atom.hydrogens:
        text += "H" + (str(atom.hydrogens) if atom.hydrogens != 1 else "")
    if atom.charge:
        text += "+" if atom.charge > 0 else "-"
        if abs(atom.charge) != 1:
            text += str(abs(atom.charge))
    return text + "]"


def bond_symbol(molecule, bond):
    first, second = bond.ends
    in_ring = bond.ring and molecule.atoms[first].aromatic and molecule.atoms[second].aromatic
    if bond.kind == 1:
        return "-" if in_ring else ""
    if bond.kind == 2:
        return "="
    if bond.kind == 3:
        return "#"
    return "" if in_ring else ":"


def canonical_smiles(molecule, ranks):
    visits = {}
    children = [[] for atom in molecule.atoms]
    closures = set()

    def visit(atom, incoming):
        visits[atom] = len(visits) + 1
        for neighbor in sorted(molecule.neighbors[atom], key=lambda number: ranks[number]):
            bond = molecule.neighbors[atom][neighbor]
            if bond is incoming or bond.ends in closures:
                continue
            if neighbor not in visits:
                children[atom].append((neighbor, bond))
                visit(neighbor, bond)
            else:
                closures.add(bond.ends)

    root = ranks.index(1)
    visit(root, None)
    assignments = {}
    occupied = set()

    def write(atom):
        parts = [atom_notation(molecule, atom)]
        neighbors = sorted(molecule.neighbors[atom], key=lambda number: visits[number])
        for neighbor in neighbors:
            bond = molecule.neighbors[atom][neighbor]
            if bond.ends not in closures:
                continue
            if bond.ends in assignments:
                number = assignments.pop(bond.ends)
                occupied.remove(number)
                symbol = ""
            else:
                number = 1
                while number in occupied:
                    number += 1
                assignments[bond.ends] = number
                occupied.add(number)
                symbol = bond_symbol(molecule, bond)
            parts.append(symbol + (str(number) if number < 10 else f"%{number:02d}"))
        for index, (child, bond) in enumerate(children[atom]):
            continuation = bond_symbol(molecule, bond) + write(child)
            parts.append("(" + continuation + ")" if index + 1 < len(children[atom]) else continuation)
        return "".join(parts)

    return write(root)


def canonicalize(molecule):
    ranks, classes = canonical_ranks(molecule)
    return canonical_smiles(molecule, ranks), classes

from collections import Counter, defaultdict, deque
from functools import cmp_to_key
from math import gcd
from pathlib import Path
from string import ascii_letters, digits

from canonical import canonicalize
from molecule import AnalysisError, Atom, BOND_TYPES, Molecule, needs_pi, organic_hydrogens, read_elements
from rings_aromatic import find_rings, kekulize
from search import embeddings, fingerprint, molecule_pattern, read_pattern_atom, tanimoto
from smiles_parser import parse_smiles


NAME_CHARACTERS = frozenset(ascii_letters + digits + "_-")
ARGUMENT_COUNTS = {"MATCH": (1, 1), "CONTAINS": (2, 2), "MATRIX": (2, 12),
                   "NEAREST": (2, 2), "WITHIN": (2, 2), "COMPARE": (2, 2), "CLUSTER": (1, 1)}
SYSTEM_KINDS = ("isolated", "fused", "spiro", "bridged")


def data_lines(filename):
    lines = Path(filename).read_text(encoding="ascii").splitlines()
    return [(number, line) for number, line in enumerate(lines, 1)
            if line and not line.startswith("#")]


def valid_name(value):
    return 1 <= len(value) <= 32 and all(character in NAME_CHARACTERS for character in value)


def valid_number(value, minimum, maximum):
    if not value or not value.isdigit() or len(value) > 1 and value[0] == "0":
        return False
    return minimum <= int(value) <= maximum


def read_threshold(value):
    parts = value.split("/")
    if len(parts) != 2:
        return None
    if not valid_number(parts[0], 0, 99) or not valid_number(parts[1], 1, 99):
        return None
    numerator, denominator = map(int, parts)
    return (numerator, denominator) if numerator <= denominator else None


def fraction_text(value):
    numerator, denominator = value
    divisor = gcd(numerator, denominator)
    return f"{numerator // divisor}/{denominator // divisor}"


def fraction_compare(first, second):
    left = first[0] * second[1]
    right = second[0] * first[1]
    return (left > right) - (left < right)


def atom_numbers(atoms, separator=","):
    return separator.join(str(atom + 1) for atom in atoms)


def member_names(molecules):
    return ",".join(molecule.name for molecule in molecules)


def analyze(molecule):
    find_rings(molecule)
    for bond in molecule.bonds.values():
        if bond.symbol is not None:
            bond.kind = BOND_TYPES[bond.symbol]
        else:
            first, second = bond.ends
            aromatic = molecule.atoms[first].aromatic and molecule.atoms[second].aromatic
            bond.kind = 4 if aromatic and bond.ring else 1
    needing = [number for number in range(len(molecule.atoms)) if needs_pi(molecule, number)]
    kekulize(molecule, needing)
    for number, atom in enumerate(molecule.atoms):
        total = molecule.bond_total(number)
        if atom.bracket:
            if total + atom.hydrogens > atom.element.valences[-1] + abs(atom.charge):
                raise AnalysisError("bad valence", atom.column)
        else:
            hydrogens = organic_hydrogens(atom, total)
            if hydrogens is None:
                raise AnalysisError("bad valence", atom.column)
            atom.hydrogens = hydrogens


def molecular_properties(molecule):
    counts = Counter(atom.element.symbol for atom in molecule.atoms)
    hydrogens = sum(atom.hydrogens for atom in molecule.atoms)
    counts["H"] += hydrogens
    symbols = sorted(symbol for symbol, count in counts.items() if count)
    if counts["C"]:
        symbols.remove("C")
        first = ["C"]
        if "H" in symbols:
            symbols.remove("H")
            first.append("H")
        symbols = first + symbols
    formula = "".join(symbol + (str(counts[symbol]) if counts[symbol] != 1 else "")
                      for symbol in symbols)
    weight = sum(atom.mass * 1000 if atom.mass else atom.element.weight for atom in molecule.atoms)
    weight += hydrogens * molecule.elements["H"].weight
    heavy = sum(atom.element.symbol != "H" for atom in molecule.atoms)
    heavy_degrees = [sum(molecule.atoms[neighbor].element.symbol != "H" for neighbor in neighbors)
                     for neighbors in molecule.neighbors]
    triple_ends = set()
    for bond in molecule.bonds.values():
        if bond.multiplicity == 3:
            triple_ends.update(bond.ends)
    rotatable = 0
    for bond in molecule.bonds.values():
        first, second = bond.ends
        if bond.multiplicity != 1 or bond.ring:
            continue
        if heavy_degrees[first] < 2 or heavy_degrees[second] < 2:
            continue
        if first not in triple_ends and second not in triple_ends:
            rotatable += 1
    donors = acceptors = 0
    for number, atom in enumerate(molecule.atoms):
        if atom.element.symbol in ("N", "O"):
            acceptors += 1
            attached = atom.hydrogens
            attached += sum(molecule.atoms[neighbor].element.symbol == "H"
                            for neighbor in molecule.neighbors[number])
            donors += attached >= 1
    violations = int(weight > 500000) + int(donors > 5) + int(acceptors > 10)
    return {"formula": formula, "weight": weight, "heavy": heavy, "rotatable": rotatable,
            "donors": donors, "acceptors": acceptors, "lipinski": "pass" if violations <= 1 else "fail",
            "charge": sum(atom.charge for atom in molecule.atoms)}


def scaffold_molecule(molecule):
    if not molecule.rings:
        return None
    remaining = set(range(len(molecule.atoms)))
    while True:
        leaf = None
        for atom in sorted(remaining - molecule.ring_atoms):
            degree = sum(neighbor in remaining for neighbor in molecule.neighbors[atom])
            if degree == 1:
                leaf = atom
                break
        if leaf is None:
            break
        remaining.remove(leaf)
    kept = set(remaining)
    for atom in remaining:
        for neighbor, bond in molecule.neighbors[atom].items():
            if neighbor not in remaining and bond.kind == 2:
                kept.add(neighbor)
    scaffold = Molecule(molecule.elements)
    renumber = {}
    for number in sorted(kept):
        original = molecule.atoms[number]
        added_hydrogens = sum(bond.multiplicity for neighbor, bond in molecule.neighbors[number].items()
                              if neighbor not in kept)
        atom = Atom(original.element, original.aromatic, original.mass, original.charge,
                    original.hydrogens + added_hydrogens, original.bracket, original.column)
        renumber[number] = scaffold.add_atom(atom)
    for original in molecule.ordered_bonds():
        first, second = original.ends
        if first in kept and second in kept:
            bond = scaffold.add_bond(renumber[first], renumber[second], original.symbol)
            bond.kind = original.kind
            bond.multiplicity = original.multiplicity
            bond.ring = original.ring
    scaffold.rings = [tuple(renumber[atom] for atom in ring) for ring in molecule.rings]
    scaffold.ring_atoms = {renumber[atom] for atom in molecule.ring_atoms}
    return scaffold


def ring_systems(molecule):
    atom_sets = [set(ring) for ring in molecule.rings]
    connections = [set() for ring in molecule.rings]
    relations = {}
    for first in range(len(atom_sets)):
        for second in range(first + 1, len(atom_sets)):
            shared = atom_sets[first].intersection(atom_sets[second])
            if not shared:
                continue
            connections[first].add(second)
            connections[second].add(first)
            if len(shared) == 1:
                relation = "spiro"
            elif len(shared) == 2:
                atom, neighbor = sorted(shared)
                relation = "fused" if neighbor in molecule.neighbors[atom] else "bridged"
            else:
                relation = "bridged"
            relations[first, second] = relation
    systems = []
    unseen = set(range(len(atom_sets)))
    while unseen:
        start = min(unseen)
        unseen.remove(start)
        component = {start}
        queue = deque([start])
        while queue:
            ring = queue.popleft()
            for neighbor in sorted(connections[ring]):
                if neighbor in unseen:
                    unseen.remove(neighbor)
                    component.add(neighbor)
                    queue.append(neighbor)
        kinds = {kind for (first, second), kind in relations.items()
                 if first in component and second in component}
        if len(component) == 1:
            kind = "isolated"
        elif "bridged" in kinds:
            kind = "bridged"
        elif "fused" in kinds:
            kind = "fused"
        else:
            kind = "spiro"
        atoms = set()
        for ring in component:
            atoms.update(atom_sets[ring])
        systems.append({"rings": sorted(component), "atoms": len(atoms), "kind": kind})
    return systems


def read_molecules(elements, causes):
    molecules = []
    errors = []
    reserved = set()
    lines = data_lines("input/molecules.smi")
    for line_number, line in lines:
        tokens = line.split(" ")
        if len(tokens) != 2 or not tokens[0] or not valid_name(tokens[1]):
            errors.append(f"line {line_number}: bad line")
            causes["bad line"] += 1
            continue
        smiles, name = tokens
        if name in reserved:
            errors.append(f"line {line_number} {name}: duplicate name")
            causes["duplicate name"] += 1
            continue
        reserved.add(name)
        try:
            molecule = parse_smiles(smiles, elements)
            analyze(molecule)
        except AnalysisError as error:
            errors.append(f"line {line_number} {name}: {error.reason} at column {error.column}")
            causes[error.reason] += 1
            continue
        molecule.name = name
        molecule.order = len(molecules)
        molecules.append(molecule)
    paragraph = [f"MOLECULES lines={len(lines)} valid={len(molecules)} errors={len(errors)}"]
    paragraph.extend(errors)
    return molecules, paragraph


def prepare_molecules(molecules):
    for molecule in molecules:
        molecule.properties = molecular_properties(molecule)
        molecule.canonical, molecule.classes = canonicalize(molecule)
        scaffold = scaffold_molecule(molecule)
        molecule.scaffold = canonicalize(scaffold)[0] if scaffold is not None else None
        molecule.systems = ring_systems(molecule)
        molecule.aromatic_rings = [all(molecule.atoms[atom].aromatic for atom in ring)
                                   for ring in molecule.rings]
        molecule.bits, molecule.paths = fingerprint(molecule)


def check_arguments(query, elements, by_name):
    kind, arguments = query["type"], query["arguments"]
    minimum, maximum = ARGUMENT_COUNTS[kind]
    if not minimum <= len(arguments) <= maximum:
        return "bad arguments"
    if kind == "MATCH":
        try:
            query["pattern"] = parse_smiles(arguments[0], elements, read_pattern_atom, pattern=True)
        except AnalysisError as error:
            return f"bad pattern {error.reason} at column {error.column}"
    elif kind == "CLUSTER":
        query["threshold"] = read_threshold(arguments[0])
        if query["threshold"] is None:
            return "bad threshold"
    elif kind in ("CONTAINS", "MATRIX", "COMPARE"):
        for name in arguments:
            if name not in by_name:
                return "unknown molecule " + name
        if len(set(arguments)) != len(arguments):
            return "repeated molecule"
    else:
        if arguments[0] not in by_name:
            return "unknown molecule " + arguments[0]
        if kind == "NEAREST":
            if not valid_number(arguments[1], 1, 99):
                return "bad count"
            query["count"] = int(arguments[1])
        else:
            query["threshold"] = read_threshold(arguments[1])
            if query["threshold"] is None:
                return "bad threshold"
    return None


def query_error(line, kind, identifier, reason, causes):
    if reason == "unknown query":
        text = f"line {line}: unknown query"
    elif reason == "bad id":
        text = f"line {line} {kind}: bad id"
    else:
        text = f"line {line} {kind} {identifier}: {reason}"
    if reason.startswith("bad pattern "):
        cause = "bad pattern"
    elif reason.startswith("unknown molecule "):
        cause = "unknown molecule"
    else:
        cause = reason
    causes[cause] += 1
    return text


def read_queries(elements, by_name, causes):
    queries = []
    errors = []
    reserved = set()
    lines = data_lines("input/queries.txt")
    for line_number, line in lines:
        tokens = line.split(" ")
        kind = tokens[0]
        identifier = tokens[1] if len(tokens) >= 2 else None
        if kind not in ARGUMENT_COUNTS:
            reason = "unknown query"
        elif identifier is None or not valid_name(identifier):
            reason = "bad id"
        elif identifier in reserved:
            reason = "duplicate id"
        else:
            reserved.add(identifier)
            query = {"type": kind, "id": identifier, "arguments": tokens[2:]}
            reason = check_arguments(query, elements, by_name)
            if reason is None:
                queries.append(query)
                continue
        errors.append(query_error(line_number, kind, identifier, reason, causes))
    paragraph = [f"QUERIES lines={len(lines)} valid={len(queries)} errors={len(errors)}"]
    paragraph.extend(errors)
    return queries, paragraph


def properties_lines(molecules):
    lines = ["name,formula,weight,heavy_atoms,rings,rotatable,donors,acceptors,lipinski"]
    for molecule in molecules:
        values = molecule.properties
        weight = values["weight"]
        row = [molecule.name, values["formula"], f"{weight // 1000}.{weight % 1000:03d}",
               str(values["heavy"]), str(len(molecule.rings)), str(values["rotatable"]),
               str(values["donors"]), str(values["acceptors"]), values["lipinski"]]
        lines.append(",".join(row))
    return lines


def canonical_paragraphs(molecules):
    by_canonical = defaultdict(list)
    by_formula = defaultdict(list)
    by_scaffold = defaultdict(list)
    acyclic = 0
    for molecule in molecules:
        by_canonical[molecule.canonical].append(molecule)
        by_formula[molecule.properties["formula"]].append(molecule)
        if molecule.scaffold is None:
            acyclic += 1
        else:
            by_scaffold[molecule.scaffold].append(molecule)
    canonical = [f"CANONICAL molecules={len(molecules)} unique={len(by_canonical)}"]
    for molecule in molecules:
        charge = molecule.properties["charge"]
        text = f"{charge:+d}" if charge else "0"
        canonical.append(f"{molecule.name} {molecule.canonical} classes={molecule.classes} charge={text}")
    groups = [(smiles, members) for smiles, members in by_canonical.items() if len(members) >= 2]
    count = sum(len(members) for smiles, members in groups)
    duplicates = [f"DUPLICATES groups={len(groups)} molecules={count}"]
    for number, (smiles, members) in enumerate(groups, 1):
        duplicates.append(f"group {number} {smiles} members={member_names(members)}")
    groups = []
    for formula, members in by_formula.items():
        forms = len({molecule.canonical for molecule in members})
        if forms >= 2:
            groups.append((formula, members, forms))
    isomers = [f"ISOMERS groups={len(groups)}"]
    for number, (formula, members, forms) in enumerate(groups, 1):
        isomers.append(f"isomer {number} {formula} forms={forms} members={member_names(members)}")
    scaffolds = [f"SCAFFOLDS distinct={len(by_scaffold)} acyclic={acyclic}"]
    groups = sorted(by_scaffold.items(), key=lambda item: (-len(item[1]), item[0]))
    for number, (smiles, members) in enumerate(groups, 1):
        scaffolds.append(f"scaffold {number} {smiles} count={len(members)} members={member_names(members)}")
    return [canonical, duplicates, isomers, scaffolds]


def ring_paragraphs(molecules):
    paragraphs = []
    sizes = Counter()
    kinds = Counter()
    total_aromatic = 0
    total_rings = 0
    for molecule in molecules:
        if not molecule.rings:
            continue
        aromatic = sum(molecule.aromatic_rings)
        total_aromatic += aromatic
        total_rings += len(molecule.rings)
        ring_bonds = sum(bond.ring for bond in molecule.bonds.values())
        paragraph = [f"MOLECULE {molecule.name} atoms={len(molecule.atoms)} bonds={len(molecule.bonds)} "
                     f"rings={len(molecule.rings)} aromatic={aromatic} systems={len(molecule.systems)} "
                     f"ring_atoms={len(molecule.ring_atoms)} ring_bonds={ring_bonds}"]
        for number, ring in enumerate(molecule.rings, 1):
            flag = "yes" if molecule.aromatic_rings[number - 1] else "no"
            hetero = sum(molecule.atoms[atom].element.symbol != "C" for atom in ring)
            paragraph.append(f"ring {number} size={len(ring)} aromatic={flag} hetero={hetero} "
                             f"atoms={atom_numbers(ring, '-')}")
            sizes[len(ring)] += 1
        for number, system in enumerate(molecule.systems, 1):
            kinds[system["kind"]] += 1
            paragraph.append(f"system {number} kind={system['kind']} rings={atom_numbers(system['rings'])} "
                             f"atoms={system['atoms']}")
        double_bonds = [atom_numbers(bond.ends, "=") for bond in molecule.ordered_bonds()
                        if bond.kind == 4 and bond.multiplicity == 2]
        paragraph.append("kekule " + (" ".join(double_bonds) if double_bonds else "-"))
        paragraphs.append(paragraph)
    summary = [f"SUMMARY molecules={len(molecules)} cyclic={len(paragraphs)} rings={total_rings} "
               f"aromatic={total_aromatic}"]
    summary.append("sizes " + (" ".join(f"{size}={sizes[size]}" for size in sorted(sizes)) if sizes else "-"))
    summary.append("systems " + " ".join(f"{kind}={kinds[kind]}" for kind in SYSTEM_KINDS))
    paragraphs.append(summary)
    return paragraphs


def substructure_paragraphs(queries, molecules, by_name):
    paragraphs = []
    patterns = hits = contains = found = 0
    for query in queries:
        kind, identifier, arguments = query["type"], query["id"], query["arguments"]
        if kind == "MATCH":
            patterns += 1
            pattern = query["pattern"]
            matches = []
            for molecule in molecules:
                count, unique, mapping = embeddings(pattern, molecule)
                if count:
                    matches.append((molecule, count, unique, mapping))
            hits += len(matches)
            total = sum(match[1] for match in matches)
            paragraph = [f"MATCH {identifier} {arguments[0]} atoms={len(pattern.atoms)} "
                         f"bonds={len(pattern.bonds)} hits={len(matches)} embeddings={total}"]
            for molecule, count, unique, mapping in matches:
                paragraph.append(f"{molecule.name} count={count} unique={unique} map={atom_numbers(mapping)}")
            if matches:
                top = max(matches, key=lambda match: match[1])
                paragraph.append(f"top {top[0].name} count={top[1]}")
            paragraphs.append(paragraph)
        elif kind == "CONTAINS":
            contains += 1
            first, second = (by_name[name] for name in arguments)
            count, unique, mapping = embeddings(molecule_pattern(first), second)
            text = f"CONTAINS {identifier} {first.name} {second.name} result="
            if count:
                found += 1
                text += f"yes count={count} unique={unique} map={atom_numbers(mapping)}"
            else:
                text += "no"
            paragraphs.append([text])
    paragraphs.append([f"SUMMARY patterns={patterns} hits={hits} contains={contains} found={found}"])
    return paragraphs


class Similarities:
    def __init__(self):
        self.cache = {}

    def get(self, first, second):
        key = tuple(sorted((first.order, second.order)))
        if key not in self.cache:
            self.cache[key] = tanimoto(first.bits, second.bits)
        return self.cache[key]


def matrix_paragraph(query, by_name, similarities):
    molecules = [by_name[name] for name in query["arguments"]]
    paragraph = [f"MATRIX {query['id']} size={len(molecules)}"]
    for first in molecules:
        row = [fraction_text(similarities.get(first, second)) for second in molecules]
        paragraph.append("row " + first.name + " " + " ".join(row))
    best_first, best_second = molecules[0], molecules[1]
    best = similarities.get(best_first, best_second)
    for index, first in enumerate(molecules):
        for second in molecules[index + 1:]:
            value = similarities.get(first, second)
            if fraction_compare(value, best) > 0:
                best_first, best_second, best = first, second, value
    paragraph.append(f"best {best_first.name} {best_second.name} {fraction_text(best)}")
    return paragraph


def ranked_neighbors(source, molecules, similarities):
    neighbors = [(molecule, similarities.get(source, molecule)) for molecule in molecules if molecule is not source]

    def compare(first, second):
        difference = fraction_compare(second[1], first[1])
        if difference:
            return difference
        return first[0].order - second[0].order

    return sorted(neighbors, key=cmp_to_key(compare))


def neighbors_paragraph(query, molecules, by_name, similarities):
    source = by_name[query["arguments"][0]]
    neighbors = ranked_neighbors(source, molecules, similarities)
    if query["type"] == "NEAREST":
        result = neighbors[:query["count"]]
        heading = f"NEAREST {query['id']} {source.name} count={len(result)}"
    else:
        threshold = query["threshold"]
        result = [(molecule, value) for molecule, value in neighbors if fraction_compare(value, threshold) >= 0]
        heading = f"WITHIN {query['id']} {source.name} threshold={fraction_text(threshold)} count={len(result)}"
    paragraph = [heading]
    for number, (molecule, value) in enumerate(result, 1):
        paragraph.append(f"{number} {molecule.name} {fraction_text(value)} common={value[0]}")
    return paragraph


def compare_paragraph(query, by_name, similarities):
    first, second = (by_name[name] for name in query["arguments"])
    value = similarities.get(first, second)
    identical = "yes" if first.canonical == second.canonical else "no"
    return [f"COMPARE {query['id']} {first.name} {second.name} bits={len(first.bits)},{len(second.bits)} "
            f"common={value[0]} union={value[1]} tanimoto={fraction_text(value)} identical={identical}"]


def cluster_paragraph(query, molecules, similarities):
    threshold = query["threshold"]
    neighbors = []
    for first in molecules:
        neighbors.append([second.order for second in molecules if second is not first
                          and fraction_compare(similarities.get(first, second), threshold) >= 0])
    order = sorted(range(len(molecules)), key=lambda number: (-len(neighbors[number]), number))
    assigned = set()
    clusters = []
    for center in order:
        if center in assigned:
            continue
        members = [center] + [neighbor for neighbor in neighbors[center] if neighbor not in assigned]
        clusters.append(members)
        assigned.update(members)
    singletons = sum(len(members) == 1 for members in clusters)
    paragraph = [f"CLUSTER {query['id']} threshold={fraction_text(threshold)} "
                 f"clusters={len(clusters)} singletons={singletons}"]
    number = 0
    for members in clusters:
        if len(members) == 1:
            continue
        number += 1
        selected = [molecules[index] for index in members]
        paragraph.append(f"cluster {number} centroid={selected[0].name} size={len(selected)} "
                         f"members={member_names(selected)}")
    return paragraph


def similarity_paragraphs(queries, molecules, by_name):
    fingerprints = [f"FINGERPRINTS molecules={len(molecules)} size=1024 depth=5"]
    fingerprints.extend(f"{molecule.name} bits={len(molecule.bits)} paths={molecule.paths}" for molecule in molecules)
    paragraphs = [fingerprints]
    similarities = Similarities()
    for query in queries:
        kind = query["type"]
        if kind == "MATRIX":
            paragraph = matrix_paragraph(query, by_name, similarities)
        elif kind in ("NEAREST", "WITHIN"):
            paragraph = neighbors_paragraph(query, molecules, by_name, similarities)
        elif kind == "COMPARE":
            paragraph = compare_paragraph(query, by_name, similarities)
        elif kind == "CLUSTER":
            paragraph = cluster_paragraph(query, molecules, similarities)
        else:
            continue
        paragraphs.append(paragraph)
    return paragraphs


def causes_paragraph(causes):
    paragraph = [f"CAUSES kinds={len(causes)}"]
    for reason, count in sorted(causes.items(), key=lambda item: (-item[1], item[0])):
        paragraph.append(f"{reason}={count}")
    return paragraph


def paragraphs_text(paragraphs):
    return "\n\n".join("\n".join(paragraph) for paragraph in paragraphs) + "\n"


def main():
    elements = read_elements("input/elements.txt")
    causes = Counter()
    molecules, molecule_errors = read_molecules(elements, causes)
    prepare_molecules(molecules)
    by_name = {molecule.name: molecule for molecule in molecules}
    queries, query_errors = read_queries(elements, by_name, causes)
    outputs = {"properties.csv": "\n".join(properties_lines(molecules)) + "\n",
               "canonical.txt": paragraphs_text(canonical_paragraphs(molecules)),
               "rings.txt": paragraphs_text(ring_paragraphs(molecules)),
               "substructure.txt": paragraphs_text(substructure_paragraphs(queries, molecules, by_name)),
               "similarity.txt": paragraphs_text(similarity_paragraphs(queries, molecules, by_name)),
               "errors.txt": paragraphs_text([molecule_errors, query_errors, causes_paragraph(causes)])}
    directory = Path("output")
    directory.mkdir(exist_ok=True)
    for filename, content in outputs.items():
        (directory / filename).write_text(content, encoding="ascii", newline="\n")


if __name__ == "__main__":
    main()

from collections import namedtuple
from pathlib import Path


Element = namedtuple("Element", "symbol number weight valences")
ORGANIC = frozenset(("B", "C", "N", "O", "P", "S", "F", "Cl", "Br", "I"))
AROMATIC = frozenset("BCNOPS")
BOND_TYPES = {"-": 1, "/": 1, "\\": 1, "=": 2, "#": 3, ":": 4}
BASE_VALUES = (0, 1, 2, 3, 1)


class AnalysisError(Exception):
    def __init__(self, reason, column):
        super().__init__(reason)
        self.reason = reason
        self.column = column


class Atom:
    def __init__(self, element, aromatic=False, mass=0, charge=0, hydrogens=0,
                 bracket=False, column=0):
        self.element = element
        self.aromatic = aromatic
        self.mass = mass
        self.charge = charge
        self.hydrogens = hydrogens
        self.bracket = bracket
        self.column = column


class Bond:
    def __init__(self, first, second, symbol):
        self.ends = tuple(sorted((first, second)))
        self.symbol = symbol
        self.kind = None
        self.multiplicity = 0
        self.ring = False


class Molecule:
    def __init__(self, elements):
        self.elements = elements
        self.atoms = []
        self.neighbors = []
        self.bonds = {}
        self.rings = []
        self.ring_atoms = set()
        self.name = ""

    def add_atom(self, atom):
        number = len(self.atoms)
        self.atoms.append(atom)
        self.neighbors.append({})
        return number

    def add_bond(self, first, second, symbol):
        bond = Bond(first, second, symbol)
        self.bonds[bond.ends] = bond
        self.neighbors[first][second] = bond
        self.neighbors[second][first] = bond
        return bond

    def ordered_bonds(self):
        return [self.bonds[ends] for ends in sorted(self.bonds)]

    def degree(self, number):
        return len(self.neighbors[number])

    def base_total(self, number):
        return sum(BASE_VALUES[bond.kind] for bond in self.neighbors[number].values())

    def bond_total(self, number):
        return sum(bond.multiplicity for bond in self.neighbors[number].values())


def read_elements(path):
    elements = {}
    for line in Path(path).read_text(encoding="ascii").splitlines():
        if not line or line.startswith("#"):
            continue
        symbol, number, weight, valences = line.split(" ")
        elements[symbol] = Element(symbol, int(number), int(weight),
                                   tuple(int(value) for value in valences.split(",")))
    return elements


def needs_pi(molecule, number, hydrogens=None):
    atom = molecule.atoms[number]
    if hydrogens is None:
        hydrogens = atom.hydrogens
    occupied = molecule.base_total(number) + hydrogens
    return atom.aromatic and atom.element.valences[0] + atom.charge >= occupied + 1


def organic_hydrogens(atom, bond_total):
    for valence in atom.element.valences:
        if valence >= bond_total:
            return valence - bond_total
    return None

from collections import deque

from molecule import AnalysisError


def breadth_first(molecule, root):
    parents = {root: None}
    queue = deque([root])
    while queue:
        atom = queue.popleft()
        for neighbor in sorted(molecule.neighbors[atom]):
            if neighbor not in parents:
                parents[neighbor] = atom
                queue.append(neighbor)
    paths = {}
    for atom in parents:
        path = []
        current = atom
        while current is not None:
            path.append(current)
            current = parents[current]
        paths[atom] = path
    return parents, paths


def ring_edges(sequence):
    return frozenset(tuple(sorted((sequence[index - 1], atom)))
                     for index, atom in enumerate(sequence))


def ring_sequence(sequence):
    first = sequence.index(min(sequence))
    forward = tuple(sequence[first:] + sequence[:first])
    backward = (forward[0],) + tuple(reversed(forward[1:]))
    return min(forward, backward)


def find_rings(molecule):
    candidates = []
    seen = set()
    bonds = sorted(molecule.bonds)
    for root in range(len(molecule.atoms)):
        parents, paths = breadth_first(molecule, root)
        for first, second in bonds:
            if parents[first] == second or parents[second] == first:
                continue
            if set(paths[first]).intersection(paths[second]) != {root}:
                continue
            sequence = list(reversed(paths[first])) + paths[second][:-1]
            edges = ring_edges(sequence)
            if edges not in seen:
                seen.add(edges)
                candidates.append((sequence, edges))
    basis = {}
    rings = []
    for sequence, original in sorted(candidates, key=lambda candidate: len(candidate[0])):
        reduced = original
        while reduced:
            pivot = max(reduced)
            if pivot not in basis:
                basis[pivot] = reduced
                rings.append(ring_sequence(sequence))
                break
            reduced = reduced.symmetric_difference(basis[pivot])
    molecule.rings = sorted(rings, key=lambda ring: (len(ring), ring))
    for ring in molecule.rings:
        molecule.ring_atoms.update(ring)
        for edge in ring_edges(ring):
            molecule.bonds[edge].ring = True


def aromatic_systems(molecule, needing):
    remaining = set(needing)
    systems = []
    while remaining:
        start = min(remaining)
        remaining.remove(start)
        system = {start}
        queue = deque([start])
        while queue:
            atom = queue.popleft()
            for neighbor, bond in sorted(molecule.neighbors[atom].items()):
                if bond.kind == 4 and neighbor in remaining:
                    remaining.remove(neighbor)
                    system.add(neighbor)
                    queue.append(neighbor)
        systems.append(system)
    return systems


def match_system(molecule, system):
    unpaired = set(system)
    pairs = []

    def search():
        if not unpaired:
            return True
        first = min(unpaired)
        unpaired.remove(first)
        for second, bond in sorted(molecule.neighbors[first].items()):
            if second not in unpaired or bond.kind != 4:
                continue
            unpaired.remove(second)
            pairs.append(bond.ends)
            if search():
                return True
            pairs.pop()
            unpaired.add(second)
        unpaired.add(first)
        return False

    return pairs if search() else None


def kekulize(molecule, needing):
    selected = set()
    for system in aromatic_systems(molecule, needing):
        pairs = match_system(molecule, system)
        if pairs is None:
            raise AnalysisError("kekulization failed", molecule.atoms[min(system)].column)
        selected.update(pairs)
    for bond in molecule.bonds.values():
        bond.multiplicity = (2 if bond.ends in selected else 1) if bond.kind == 4 else bond.kind

from molecule import AnalysisError, BOND_TYPES, Molecule
from smiles_parser import read_organic


class PatternAtom:
    def __init__(self, choices=None, aromatic=None):
        self.choices = choices
        self.aromatic = aromatic

    def matches(self, atom):
        if self.choices is not None:
            return (atom.element.symbol, atom.aromatic) in self.choices
        return self.aromatic is None or atom.aromatic == self.aromatic


def read_pattern_atom(text, position, elements):
    character = text[position]
    if character in ("*", "A", "a"):
        aromatic = None if character == "*" else character == "a"
        return PatternAtom(aromatic=aromatic), position + 1
    if character == "[":
        end = text.find("]", position + 1)
        if end < 0:
            raise AnalysisError("unclosed bracket", position + 1)
        choices = set()
        for item in text[position + 1:end].split(","):
            organic = read_organic(item, 0)
            if organic is None or organic[2] != len(item):
                raise AnalysisError("bad bracket atom", position + 1)
            choices.add(organic[:2])
        return PatternAtom(choices), end + 1
    organic = read_organic(text, position)
    if organic is None:
        raise AnalysisError("unexpected character", position + 1)
    return PatternAtom({organic[:2]}), organic[2]


def molecule_pattern(molecule):
    pattern = Molecule(molecule.elements)
    for atom in molecule.atoms:
        pattern.add_atom(PatternAtom({(atom.element.symbol, atom.aromatic)}))
    for bond in molecule.ordered_bonds():
        pattern.add_bond(*bond.ends, bond.kind)
    return pattern


def bond_matches(pattern_bond, molecule_bond):
    symbol = pattern_bond.symbol
    if symbol is None:
        return molecule_bond.kind in (1, 4)
    if symbol == "~":
        return True
    kind = BOND_TYPES[symbol] if isinstance(symbol, str) else symbol
    return molecule_bond.kind == kind


def embeddings(pattern, molecule):
    if len(pattern.atoms) > len(molecule.atoms):
        return 0, 0, None
    candidates = [[number for number, atom in enumerate(molecule.atoms)
                   if pattern_atom.matches(atom) and molecule.degree(number) >= pattern.degree(index)]
                  for index, pattern_atom in enumerate(pattern.atoms)]
    earlier = [[(neighbor, bond) for neighbor, bond in neighbors.items() if neighbor < number]
               for number, neighbors in enumerate(pattern.neighbors)]
    mapping = []
    used = set()
    unique = set()
    count = 0
    first_mapping = None

    def assign(index):
        nonlocal count, first_mapping
        if index == len(pattern.atoms):
            count += 1
            unique.add(frozenset(used))
            if first_mapping is None:
                first_mapping = tuple(mapping)
            return
        for atom in candidates[index]:
            if atom in used:
                continue
            for neighbor, bond in earlier[index]:
                target_bond = molecule.neighbors[atom].get(mapping[neighbor])
                if target_bond is None or not bond_matches(bond, target_bond):
                    break
            else:
                mapping.append(atom)
                used.add(atom)
                assign(index + 1)
                used.remove(atom)
                mapping.pop()

    assign(0)
    return count, len(unique), first_mapping


def fingerprint(molecule):
    codes = [16 * atom.element.number + 8 * int(atom.aromatic) + molecule.degree(number)
             for number, atom in enumerate(molecule.atoms)]
    bits = set()
    count = 0
    used = set()

    def extend(atom, depth, value):
        nonlocal count
        count += 1
        bits.add(value % 1024)
        if depth == 5:
            return
        for neighbor, bond in sorted(molecule.neighbors[atom].items()):
            if neighbor in used:
                continue
            next_value = (value * 31 + bond.kind) % 1000003
            next_value = (next_value * 31 + codes[neighbor]) % 1000003
            used.add(neighbor)
            extend(neighbor, depth + 1, next_value)
            used.remove(neighbor)

    for atom, code in enumerate(codes):
        used.add(atom)
        extend(atom, 0, code)
        used.remove(atom)
    return frozenset(bits), count


def tanimoto(first, second):
    common = len(first.intersection(second))
    return common, len(first) + len(second) - common

from molecule import AnalysisError, Atom, BOND_TYPES, Molecule


def read_organic(text, position):
    pair = text[position:position + 2]
    if pair in ("Cl", "Br"):
        return pair, False, position + 2
    character = text[position:position + 1]
    if character and character in "BCNOPSFI":
        return character, False, position + 1
    if character and character in "bcnops":
        return character.upper(), True, position + 1
    return None


def read_bracket(content, elements, column):
    position = 0
    while position < len(content) and content[position].isdigit():
        position += 1
    if position >= 4 or position and content[0] == "0":
        raise AnalysisError("bad bracket atom", column)
    mass = int(content[:position]) if position else 0
    if position == len(content):
        raise AnalysisError("bad bracket atom", column)
    character = content[position]
    if character in "bcnops":
        symbol, aromatic = character.upper(), True
        position += 1
    elif "A" <= character <= "Z":
        pair = content[position:position + 2]
        if len(pair) == 2 and "a" <= pair[1] <= "z" and pair in elements:
            symbol = pair
            position += 2
        elif character in elements:
            symbol = character
            position += 1
        else:
            raise AnalysisError("unknown element", column)
        aromatic = False
    else:
        raise AnalysisError("bad bracket atom", column)
    if content[position:position + 2] == "@@":
        position += 2
    elif content[position:position + 1] == "@":
        position += 1
    hydrogens = 0
    if content[position:position + 1] == "H":
        hydrogens = 1
        position += 1
        if position < len(content) and content[position].isdigit():
            hydrogens = int(content[position])
            position += 1
    charge = 0
    if content[position:position + 1] in ("+", "-"):
        charge = 1 if content[position] == "+" else -1
        position += 1
        if position < len(content) and content[position] in "123456789":
            charge *= int(content[position])
            position += 1
    if position != len(content):
        raise AnalysisError("bad bracket atom", column)
    return Atom(elements[symbol], aromatic, mass, charge, hydrogens, True, column)


def read_atom(text, position, elements):
    if text[position] == "[":
        end = text.find("]", position + 1)
        if end < 0:
            raise AnalysisError("unclosed bracket", position + 1)
        return read_bracket(text[position + 1:end], elements, position + 1), end + 1
    organic = read_organic(text, position)
    if organic is None:
        raise AnalysisError("unexpected character", position + 1)
    symbol, aromatic, end = organic
    return Atom(elements[symbol], aromatic, column=position + 1), end


def parse_smiles(text, elements, atom_reader=None, pattern=False):
    molecule = Molecule(elements)
    atom_reader = read_atom if atom_reader is None else atom_reader
    symbols = {"-": 1, "=": 2, "#": 3, ":": 4, "~": 5} if pattern else BOND_TYPES
    current = pending = None
    branches = []
    open_rings = {}
    position = 0
    while position < len(text):
        character = text[position]
        column = position + 1
        if character in symbols:
            if current is None or pending is not None:
                raise AnalysisError("misplaced bond", column)
            pending = character, column
            position += 1
        elif character == "(":
            if current is None or pending is not None or text[position - 1] == "(":
                raise AnalysisError("misplaced branch", column)
            branches.append((current, column))
            position += 1
        elif character == ")":
            if not branches:
                raise AnalysisError("unmatched parenthesis", column)
            if pending is not None:
                raise AnalysisError("dangling bond", pending[1])
            if text[position - 1] == "(":
                raise AnalysisError("empty branch", column)
            current, opening = branches.pop()
            position += 1
        elif character.isdigit() or character == "%":
            if current is None:
                raise AnalysisError("misplaced ring closure", column)
            if character == "%":
                digits = text[position + 1:position + 3]
                if len(digits) != 2 or not digits.isdigit():
                    raise AnalysisError("bad ring number", column)
                ring = int(digits)
                position += 3
            else:
                ring = int(character)
                position += 1
            symbol = pending[0] if pending is not None else None
            pending = None
            if ring not in open_rings:
                open_rings[ring] = current, symbol, column
                continue
            first, initial_symbol, opening = open_rings[ring]
            if first == current:
                raise AnalysisError("self bond", column)
            if initial_symbol is not None and symbol is not None and symbols[initial_symbol] != symbols[symbol]:
                raise AnalysisError("ring bond mismatch", column)
            if current in molecule.neighbors[first]:
                raise AnalysisError("duplicate bond", column)
            molecule.add_bond(first, current, symbol if symbol is not None else initial_symbol)
            del open_rings[ring]
        else:
            atom, position = atom_reader(text, position, elements)
            new_atom = molecule.add_atom(atom)
            if current is not None:
                molecule.add_bond(current, new_atom, pending[0] if pending is not None else None)
            current = new_atom
            pending = None
    if pending is not None:
        raise AnalysisError("dangling bond", pending[1])
    if branches:
        raise AnalysisError("unmatched parenthesis", branches[0][1])
    if open_rings:
        raise AnalysisError("unclosed ring", min(record[2] for record in open_rings.values()))
    return molecule
